// Текст ТЗ из Clickable Mail → тело запроса к OpenRouter. Модель и промпт задаёт этот узел, а не приложение:
// вебхук открыт всем, и через него нельзя гонять свои запросы на ключе. Из запроса берётся только text.
// Шаблон запроса вписывает n8n/tools/sync-brief-plan.ts из src/brief/prompt.ts — руками не править.
const body = $('Webhook').first().json.body || {};
const MAX = 20000;
const fail = error => [{ json: { kind: 'error', error } }];
if (typeof body.text !== 'string') return fail('В запросе нет текста ТЗ');
const text = body.text.trim();
if (!text) return fail('ТЗ пустое');
if (text.length > MAX) return fail(`ТЗ длиннее 20 000 знаков (${text.length}) — сократите`);
