// Ответ OpenRouter → { ok: true, brief, model, usage } или { ok: false, error } с понятной причиной.
// brief проверяет приложение (validateBrief): здесь — только «это JSON-объект».
const r = $json || {};
const fail = error => [{ json: { ok: false, error } }];
if (r.error) {
  const e = r.error;
  const msg = typeof e === 'string' ? e : (e.message || 'неизвестная ошибка');
  const raw = e && e.metadata && e.metadata.raw ? ' — ' + String(e.metadata.raw).slice(0, 300) : '';
  return fail('OpenRouter: ' + msg + raw);
}
const choice = (r.choices || [])[0] || {};
const content = choice.message && choice.message.content;
if (typeof content !== 'string' || !content.trim()) return fail('Модель не вернула ответ');
if (choice.finish_reason === 'length') return fail('Ответ модели обрезан: ТЗ слишком большое для одного ответа');
let brief;
try { brief = JSON.parse(content.replace(/^\s*```(?:json)?\s*|\s*```\s*$/g, '')); } catch (e) { return fail('Модель вернула не JSON'); }
